function renderSlots(template, values) {
  if (
    typeof template !== "string" ||
    values === null ||
    typeof values !== "object" ||
    Array.isArray(values)
  ) {
    return null;
  }

  for (const key of Object.keys(values)) {
    if (typeof values[key] !== "string") return null;
  }

  const slotPattern = /\{\{([A-Za-z][A-Za-z0-9_]*)\}\}/g;
  let result = "";
  let lastIndex = 0;
  let match;

  while ((match = slotPattern.exec(template)) !== null) {
    const start = match.index;
    const raw = match[0];
    const key = match[1];
    const escaped = start > 0 && template[start - 1] === "\\";

    result += template.slice(lastIndex, escaped ? start - 1 : start);

    if (
      !escaped &&
      Object.prototype.hasOwnProperty.call(values, key)
    ) {
      result += values[key];
    } else {
      result += raw;
    }

    lastIndex = start + raw.length;
  }

  return result + template.slice(lastIndex);
}
